const last_reply = $('[45] Set last_reply (LATEST by date_received DESC)').first().json.last_reply.data[0]
const scheduled = $("[49] Bison: GET /leads/{lead_id}/scheduled-emails").first().json.data || [];
const stepsResp = $input.first().json.data;
const sequenceSteps = stepsResp.sequence_steps|| [];

const scheduledRow = scheduled.find(s => s.id === last_reply.scheduled_email_id) || {};
const sequenceStepId = scheduledRow.sequence_step_id ?? null;
const sequenceStepRow = sequenceSteps.find(s => s.id === sequenceStepId) || {};
const firstEmailDateIso = scheduledRow.sent_at ?? null;
const subject = scheduledRow.email_subject ?? "";

let responseTimeHours = null;
if (firstEmailDateIso && last_reply.date_received) {
  responseTimeHours = (new Date(last_reply.date_received).getTime() - new Date(firstEmailDateIso).getTime()) / 1000 / 3600;
}

let responseTimeBucket = "another day";
if (responseTimeHours !== null) {
  if (responseTimeHours < 0.25) responseTimeBucket = "less than 15 minutes";
  else if (responseTimeHours < 1) responseTimeBucket = "less than 1 hour";
  else if (responseTimeHours < 12) responseTimeBucket = "less than 12 hours";
  else responseTimeBucket = "another day";
}

return [{ json: {
  last_reply,
  sequence_step_id: sequenceStepId,
  sequence_step_order: sequenceStepRow.order ?? null,
  first_email_date: last_reply.date_received,
  response_time_hours: responseTimeHours,
  response_time_bucket: responseTimeBucket,
  subject,
}}];

value.QUALIFICATION:
={{ (() => {
  try {
    // The tag set is the lead's state; data.tag_name is only what changed just now. Reading the
    // event meant a later preMQL tag demoted the sheet row while promote_contact_to_lead, which is
    // upgrade-only, kept MQL — 102 leads disagreed between the two stores because of it.
    const tags = $('[40] Bison: GET /leads/{taggable_id}').first().json?.data?.tags || [];
    const names = tags.map(t => String(t?.name ?? t ?? '').trim().toLowerCase());
    if (names.includes('interested') || names.includes('mql')) return 'MQL';
    if (names.includes('premql') || names.includes('pre-mql')) return 'preMQL';
    // No qualifying tag on the lead at all: fall back to the firing event, as before.
    const tagName = $('When Called by HUB').first().json.data?.tag_name;
    return String(tagName || '').toLowerCase() === 'interested' ? 'MQL' : 'preMQL';
  } catch (e) {
    return '';
  }
})() }}

