parameters.jsonBody:
={{ (() => {
  const safe = (fn, fallback = '') => {
    try {
      const value = fn();
      return value === undefined || value === null ? fallback : value;
    } catch (e) {
      return fallback;
    }
  };

  const pick = (...sources) => {
    for (const fn of sources) {
      try {
        const v = fn();
        if (v !== undefined && v !== null && v !== '') return v;
      } catch (e) {}
    }
    return '';
  };

  const str = (value) => {
    if (value === undefined || value === null) return '';
    return String(value);
  };

  // Converts JS Date / ISO date string to Google Sheets serial date number.
  // Google Sheets stores dates as numbers: 1970-01-01 = 25569.
  const toGoogleSheetsDateSerial = (value) => {
    if (value === undefined || value === null || value === '') return null;

    const d = new Date(value);
    if (Number.isNaN(d.getTime())) return null;

    // Date only, no time component.
    return Math.floor(d.getTime() / 86400000) + 25569;
  };

  const makeCell = (value, index) => {
    // Column index 8 = LEAD RECEIVED
    // Send it as a real Google Sheets date, not as text.
    if (index === 8) {
      const serial = toGoogleSheetsDateSerial(value);

      if (serial === null) {
        return {
          userEnteredValue: { stringValue: '' }
        };
      }

      return {
        userEnteredValue: {
          numberValue: serial
        },
        userEnteredFormat: {
          numberFormat: {
            type: 'DATE',
            pattern: 'mm/dd/yyyy'
          }
        }
      };
    }

    return {
      userEnteredValue: {
        stringValue: str(value)
      }
    };
  };

  const sheet = safe(
    () => $json.sheets.find(sheet => sheet.properties?.title === 'Leads'),
    null
  );
  if (!sheet) throw new Error('Sheet "Leads" not found');

const table = safe(
  () =>
    (sheet.tables || []).find(table => table.name === 'Leads') ||
    (sheet.tables || []).find(table => table.name === 'Table3') ||
    (sheet.tables || [])[0],
  null
);

if (!table) {
  throw new Error('No table found inside sheet "Leads"');
}

  // --- Sources ---
  const snovProspect = () => $('[226+227+228] Pick Snovio output body').item.json.snovio_body?.data?.[0];
  const ai           = () => $('[286] Parse AI output + set phone').item.json.ai || {};
  const bisonLead    = () => $('[40] Bison: GET /leads/{taggable_id}').item.json.data || {};
  const pickedReply  = () => $('[226+227+228] Pick Snovio output body').item.json.last_reply || {};

  // --- Phone (Lusha → AI extraction; tracked via phoneSource) ---
  const phoneNumber = safe(() => {
    if ($('[287] Set phone from Lusha').isExecuted) {
      return $('[287] Set phone from Lusha').item.json.phoneNumber;
    }
    return $('[286] Parse AI output + set phone').item.json.phoneNumber;
  });

  const phoneSource = safe(() => {
    if ($('[287] Set phone from Lusha').isExecuted) {
      return $('[287] Set phone from Lusha').item.json.phoneSource;
    }
    return $('[286] Parse AI output + set phone').item.json.phoneSource;
  });

  // --- Cascaded fields: Snov.io → AI → Bison ---
  const fullName = pick(
    () => `${snovProspect()?.firstName || ''} ${snovProspect()?.lastName || ''}`.trim(),
    () => `${ai().first_name || ''} ${ai().last_name || ''}`.trim(),
    () => `${bisonLead().first_name || ''} ${bisonLead().last_name || ''}`.trim(),
  );

  const jobTitle = pick(
    () => snovProspect()?.currentJob?.[0]?.position,
    () => ai().lead_position,
    () => bisonLead().title,
  );

  const companyName = pick(
    () => snovProspect()?.currentJob?.[0]?.companyName,
    () => ai().company_name,
    () => bisonLead().company,
  );

  const industry = pick(
    () => snovProspect()?.industry,
    () => ai().company_industry,
  );

  const headcount = pick(
    () => snovProspect()?.currentJob?.[0]?.size,
    () => ai().company_size,
  );

  const linkedinUrl = pick(
    () => (snovProspect()?.social || []).find(s => s.type === 'linkedinProfile')?.link,
    () => ai().person_linkedin,
  );

  const country = pick(
    () => snovProspect()?.country,
  );

  // E-MAIL — Bison is canonical (lead identifier); reply email as fallback
  const email = pick(
    () => bisonLead().email,
    () => pickedReply().from_email_address,
  );

  const website = pick(
    () => {
      const e = bisonLead().email;
      return e ? e.extractDomain() : '';
    },
    () => ai().company_website,
  );

  // --- Other fields (single source) ---
  // Keep raw ISO/date value here. Do NOT format to 'MM/dd/yyyy' string.
  // Formatting is handled in makeCell() via Google Sheets numberFormat.
  const leadReceived = safe(() => {
    return $('[226+227+228] Pick Snovio output body').item.json.first_email_date;
  });

  const campaignName  = safe(() => $('[52] Bison: GET /campaigns/{id}').item.json.data?.name);
  const messageTitle  = safe(() => $('[226+227+228] Pick Snovio output body').item.json.subject);
  const messageNumber = safe(() => $('[226+227+228] Pick Snovio output body').item.json.sequence_step_order);
  const responseTime  = safe(() => $('[226+227+228] Pick Snovio output body').item.json.response_time_bucket);

  const qualification = safe(() => {
    const tagName = $('When Called by HUB').item.json.data?.tag_name;
    return String(tagName || '').toLowerCase() === 'interested' ? 'MQL' : 'preMQL';
  });

  const emailText = safe(() => pickedReply().text_body);
  const campaignId = safe(() => pickedReply().campaign_id);

  const values = [
    fullName,        // 0  FULL NAME
    jobTitle,        // 1  JOB TITLE
    email,           // 2  E-MAIL
    phoneNumber,     // 3  Phone Number
    phoneSource,     // 4  Phone Source
    companyName,     // 5  COMPANY NAME
    industry,        // 6  INDUSTRY
    headcount,       // 7  HEADCOUNT
    leadReceived,    // 8  LEAD RECEIVED — real Sheet date
    campaignName,    // 9  CAMPAIGN NAME
    messageTitle,    // 10 MESSAGE TITLE
    messageNumber,   // 11 MESSAGE #
    website,         // 12 WEBSITE
    qualification,   // 13 QUALIFICATION
    responseTime,    // 14 LEAD RESPONSE TIME
    '',              // 15
    '',              // 16
    '',              // 17
    '',              // 18
    '',              // 19
    '',              // 20
    emailText,       // 21 Mail from lead
    '',              // 22
    '',              // 23
    campaignId,      // 24 Campaign ID
    '',              // 25
    '',              // 26
    linkedinUrl,     // 27 LinkedIn URL
    country,         // 28 Country
  ];

  return JSON.stringify({
    requests: [
      {
        appendCells: {
          sheetId: Number(sheet.properties.sheetId),
          tableId: String(table.tableId),
          rows: [
            {
              values: values.map((value, index) => makeCell(value, index))
            }
          ],
          fields: 'userEnteredValue,userEnteredFormat.numberFormat'
        }
      }
    ]
  });
})() }}
